from functools import lru_cache
class Solution:
    def numMovesStones(self, a: int, b: int, c: int) -> list[int]:
        start = tuple(sorted((a, b, c)))
        def moves(s):
            x, y, z = s
            res = set()
            for k in range(x + 1, z):
                if k != y:
                    res.add(tuple(sorted((k, y, z))))
                    res.add(tuple(sorted((x, k, z))))
            return res
        from collections import deque
        dist = {start: 0}
        q = deque([start])
        mn = 0 if start[2] - start[0] == 2 else None
        while q:
            s = q.popleft()
            for ns in moves(s):
                if ns not in dist:
                    dist[ns] = dist[s] + 1
                    if ns[2] - ns[0] == 2:
                        mn = dist[ns] if mn is None else min(mn, dist[ns])
                    q.append(ns)
        @lru_cache(None)
        def longest(s):
            if s[2] - s[0] == 2:
                return 0
            return max(longest(ns) for ns in moves(s)) + 1
        return [mn, longest(start)]

