#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<int> numMovesStones(int a, int b, int c) {
        vector<int> v = {a, b, c};
        sort(v.begin(), v.end());
        map<vector<int>, int> dist;
        queue<vector<int>> q;
        dist[v] = 0; q.push(v);
        int mn = INT_MAX;
        while (!q.empty()) {
            auto s = q.front(); q.pop();
            if (s[2] - s[0] == 2) { mn = min(mn, dist[s]); continue; }
            auto push = [&](vector<int> t) {
                sort(t.begin(), t.end());
                if (!dist.count(t)) { dist[t] = dist[s] + 1; q.push(t); }
            };
            for (int k = s[0] + 1; k < s[2]; k++) {
                if (k != s[1]) { push({k, s[1], s[2]}); push({s[0], k, s[2]}); }
            }
        }
        map<vector<int>, int> memo;
        function<int(vector<int>)> longest = [&](vector<int> s) -> int {
            if (memo.count(s)) return memo[s];
            if (s[2] - s[0] == 2) return memo[s] = 0;
            int best = 0;
            for (int k = s[0] + 1; k < s[2]; k++) {
                if (k == s[1]) continue;
                vector<int> t1 = {k, s[1], s[2]}, t2 = {s[0], k, s[2]};
                sort(t1.begin(), t1.end()); sort(t2.begin(), t2.end());
                best = max(best, max(longest(t1), longest(t2)));
            }
            return memo[s] = best + 1;
        };
        return {mn, longest(v)};
    }
};

