import java.util.*;
class Solution {
    public int[] numMovesStones(int a, int b, int c) {
        int[] st = {a, b, c};
        Arrays.sort(st);
        Map<List<Integer>, Integer> dist = new HashMap<>();
        Queue<List<Integer>> q = new ArrayDeque<>();
        List<Integer> start = List.of(st[0], st[1], st[2]);
        dist.put(start, 0); q.add(start);
        int mn = Integer.MAX_VALUE;
        while (!q.isEmpty()) {
            List<Integer> s = q.poll();
            int x = s.get(0), y = s.get(1), z = s.get(2);
            if (z - x == 2) { mn = Math.min(mn, dist.get(s)); continue; }
            for (int k = x + 1; k < z; k++) {
                if (k == y) continue;
                int[][] opts = {{k, y, z}, {x, k, z}};
                for (int[] o : opts) {
                    Arrays.sort(o);
                    List<Integer> t = List.of(o[0], o[1], o[2]);
                    if (!dist.containsKey(t)) { dist.put(t, dist.get(s) + 1); q.add(t); }
                }
            }
        }
        Map<List<Integer>, Integer> memo = new HashMap<>();
        int mx = longest(start, memo);
        return new int[]{mn, mx};
    }
    private int longest(List<Integer> s, Map<List<Integer>, Integer> memo) {
        if (memo.containsKey(s)) return memo.get(s);
        int x = s.get(0), y = s.get(1), z = s.get(2);
        if (z - x == 2) { memo.put(s, 0); return 0; }
        int best = 0;
        for (int k = x + 1; k < z; k++) {
            if (k == y) continue;
            int[][] opts = {{k, y, z}, {x, k, z}};
            for (int[] o : opts) {
                Arrays.sort(o);
                best = Math.max(best, longest(List.of(o[0], o[1], o[2]), memo));
            }
        }
        memo.put(s, best + 1);
        return best + 1;
    }
}

