/**
 * @param {number} a
 * @param {number} b
 * @param {number} c
 * @return {number[]}
 */
var numMovesStones = function(a, b, c) {
    const key = s => s.join(',');
    let start = [a, b, c].sort((p, q) => p - q);
    const getMoves = s => {
        const [x, y, z] = s, res = [];
        for (let k = x + 1; k < z; k++) {
            if (k === y) continue;
            res.push([k, y, z].sort((p, q) => p - q));
            res.push([x, k, z].sort((p, q) => p - q));
        }
        return res;
    };
    const dist = new Map([[key(start), 0]]);
    const q = [start];
    let mn = Infinity;
    while (q.length) {
        const s = q.shift();
        if (s[2] - s[0] === 2) { mn = Math.min(mn, dist.get(key(s))); continue; }
        for (const ns of getMoves(s)) {
            if (!dist.has(key(ns))) {
                dist.set(key(ns), dist.get(key(s)) + 1);
                q.push(ns);
            }
        }
    }
    const memo = new Map();
    const longest = s => {
        if (s[2] - s[0] === 2) return 0;
        const k = key(s);
        if (memo.has(k)) return memo.get(k);
        let best = 0;
        for (const ns of getMoves(s)) best = Math.max(best, longest(ns));
        memo.set(k, best + 1);
        return best + 1;
    };
    return [mn, longest(start)];
};

