    def numMovesStones(self, a: int, b: int, c: int) -> list[int]:
        x, y, z = sorted((a, b, c))
        g1, g2 = y - x, z - y
        if g1 == 1 and g2 == 1:
            return [0, 0]
        mn = 1 if g1 <= 2 or g2 <= 2 else 2
        return [mn, (g1 - 1) + (g2 - 1)]

